const input = $input.first().json.body ?? $input.first().json;
const text = String(input.text ?? '').trim();
const forceError = Boolean(input.force_error);
const requestedGeminiModel = String(input.gemini_model ?? '').trim();
const geminiModel = requestedGeminiModel || $env.GEMINI_MODEL || 'gemini-3.1-flash-lite';
const anthropicModel = $env.ANTHROPIC_MODEL || 'claude-sonnet-4-5';

if (!text) {
  return [{ json: { ok: false, statusCode: 400, error: 'Text is required.' } }];
}

const startedAt = new Date();
let answer = '';
let usedModel = 'gemini';
let status = 'success';
let errorMessage = '';

function describeError(error) {
  if (!error) return 'Unknown error';
  const parts = [error.message, error.description, error.response?.body?.error?.message, error.response?.body?.message]
    .filter(Boolean)
    .map(String);
  return parts.length > 0 ? parts.join(' | ') : JSON.stringify(error);
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function requestJson(options) {
  return await this.helpers.httpRequest({
    ...options,
    json: true,
    timeout: 30000,
  });
}

async function callGeminiOnce() {
  const data = await requestJson.call(this, {
    method: 'POST',
    url: `https://generativelanguage.googleapis.com/v1beta/models/${geminiModel}:generateContent`,
    headers: {
      'content-type': 'application/json',
      'x-goog-api-key': $env.GEMINI_API_KEY,
    },
    body: { contents: [{ parts: [{ text }] }] },
  });

  const content = data.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!content) throw new Error(data.error?.message ?? 'Gemini returned an empty response.');
  return content;
}

async function callGemini() {
  if (forceError) throw new Error('Forced Gemini failure for debug failover.');
  if (!$env.GEMINI_API_KEY) throw new Error('GEMINI_API_KEY is missing in n8n environment.');

  let lastError;
  for (let attempt = 1; attempt <= 2; attempt += 1) {
    try {
      return await callGeminiOnce.call(this);
    } catch (error) {
      lastError = error;
      if (attempt < 2) await sleep(700);
    }
  }
  throw new Error(`Gemini ${geminiModel} failed after retry: ${describeError(lastError)}`);
}

async function callClaude() {
  if (!$env.ANTHROPIC_API_KEY) throw new Error('ANTHROPIC_API_KEY is missing in n8n environment.');

  const data = await requestJson.call(this, {
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'content-type': 'application/json',
      'x-api-key': $env.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
    },
    body: {
      model: anthropicModel,
      max_tokens: 1200,
      messages: [{ role: 'user', content: text }],
    },
  });

  const content = data.content?.[0]?.text;
  if (!content) throw new Error(data.error?.message ?? 'Claude returned an empty response.');
  return content;
}

try {
  answer = await callGemini.call(this);
} catch (geminiError) {
  const geminiMessage = describeError(geminiError);
  try {
    answer = await callClaude.call(this);
    usedModel = 'claude';
    status = 'fallback_success';
    errorMessage = geminiMessage;
  } catch (claudeError) {
    const finishedAt = new Date();
    return [{
      json: {
        ok: false,
        statusCode: 503,
        error: `Gemini failed: ${geminiMessage}; Claude failed: ${describeError(claudeError)}`,
        startedAt: startedAt.toISOString(),
        finishedAt: finishedAt.toISOString(),
      },
    }];
  }
}

const finishedAt = new Date();
const executionTimeMs = finishedAt.getTime() - startedAt.getTime();
let finalStatus = status;

try {
  await requestJson.call(this, {
    method: 'POST',
    url: `${$env.SUPABASE_URL}/rest/v1/ai_request_logs`,
    headers: {
      apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
      authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
      'content-type': 'application/json',
      prefer: 'return=minimal',
    },
    body: {
      input_text: text,
      response_text: answer,
      used_model: usedModel,
      status,
      force_error: forceError,
      error_message: errorMessage || null,
      started_at: startedAt.toISOString(),
      finished_at: finishedAt.toISOString(),
      execution_time_ms: executionTimeMs,
    },
  });
} catch {
  finalStatus = 'db_write_failed';
}

return [{ json: { ok: true, answer, usedModel, status: finalStatus, executionTimeMs } }];
